      const n = name(x + dx, y, z + dz);
      c[s] = String(FENCE.test(n) || (GATE.test(n) && (s === "east" || s === "west")));
    }
    return c;
  };
  const states = fenceCells.map(([x, y, z]) => [x, y, z, name(x, y, z), link(x, y, z)]);
  for (const [x, y, z, block, state] of states) g.set(x, y, z, block, state);
}
